import json, sqlite3, os, collections, sys
D = os.path.dirname(os.path.abspath(__file__))
L = lambda f: json.load(open(os.path.join(D, f), encoding="utf-8-sig"))
deps = L("field_deps.json")
ns = {r["Id"]: r["NamespacePrefix"] for r in L("fields_ns.json")["result"]["records"]}
flows = L("flows.json")["result"]["records"]
db = sqlite3.connect(sys.argv[1])

def local_in(cid):
    return db.execute("SELECT e.src, e.kind FROM edge e WHERE e.dst=?", (cid,)).fetchall()
def local_comp(cid):
    return db.execute("SELECT path, label FROM component WHERE id=?", (cid,)).fetchone()

print("== d0 candidates: unmanaged, 0 org deps, in repo, 0 local non-permission edges")
n = 0
for x in deps:
    if x["count"] or ns.get(x["Id"]): continue
    cid = f"CustomField:Account.{x['DeveloperName']}__c"
    c = local_comp(cid)
    if not c: continue
    inc = [e for e in local_in(cid) if not e[0].startswith(("PermissionSet:", "Profile:"))]
    if not inc:
        n += 1
        if n <= 15: print(" ", x["DeveloperName"], "|", c[1])
print("  total", n)

print("== d1 candidates: unmanaged, 1-10 deps incl Flow+FlexiPage or Flow/FlexiPage")
for x in sorted(deps, key=lambda x: x["count"]):
    if not (1 <= x["count"] <= 10) or ns.get(x["Id"]): continue
    t = collections.Counter(a for a, _ in x["deps"])
    if "Flow" in t and "FlexiPage" in t:
        print(" ", x["DeveloperName"], x["count"], dict(t), bool(local_comp(f"CustomField:Account.{x['DeveloperName']}__c")))

print("== flow candidates: active, unmanaged, in repo, 0 local incoming edges (excluding perms)")
n = 0
for f in flows:
    if f["NamespacePrefix"]: continue
    cid = f"Flow:{f['DeveloperName']}"
    c = local_comp(cid)
    if not c: continue
    inc = [e for e in local_in(cid) if not e[0].startswith(("PermissionSet:", "Profile:"))]
    if not inc:
        n += 1
        if "Account" in f["DeveloperName"] and n < 400: print(" ", f["DeveloperName"], "|", c[1])
print("  total", n)

